CREATE FUNCTION public.merge_game_json(base jsonb, local_value jsonb, remote_value jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE result jsonb; k text; BEGIN IF local_value IS NULL OR local_value = base THEN RETURN remote_value; END IF; IF remote_value IS NULL OR remote_value = base THEN RETURN local_value; END IF; IF jsonb_typeof(local_value)='object' AND jsonb_typeof(remote_value)='object' THEN result:=remote_value; FOR k IN SELECT jsonb_object_keys(local_value) LOOP result:=jsonb_set(result,ARRAY[k],coalesce(public.merge_game_json(base->k,local_value->k,remote_value->k),'null'::jsonb)); END LOOP; RETURN result; END IF; RETURN remote_value; END $$;
ALTER FUNCTION public.sync_game_progress(jsonb,jsonb,jsonb,text,integer) RENAME TO apply_game_progress;
REVOKE ALL ON FUNCTION public.apply_game_progress(jsonb,jsonb,jsonb,text,integer) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.sync_game_progress_safe(p_intro jsonb,p_challenge jsonb,p_draft jsonb,p_path text,p_offset integer DEFAULT 0,p_base jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); saved public.participant_progress; merged_intro jsonb; merged_challenge jsonb; merged_draft jsonb; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(uid::text,0)); SELECT * INTO saved FROM public.participant_progress WHERE user_id=uid FOR UPDATE; merged_intro:=public.merge_game_json(p_base->'intro',p_intro,saved.intro); merged_challenge:=public.merge_game_json(p_base->'challenge',p_challenge,saved.challenge); merged_draft:=public.merge_game_json(p_base->'intro_draft',p_draft,saved.intro_draft); PERFORM public.apply_game_progress(merged_intro,merged_challenge,merged_draft,p_path,p_offset); SELECT * INTO saved FROM public.participant_progress WHERE user_id=uid; RETURN jsonb_build_object('intro',saved.intro,'challenge',saved.challenge,'intro_draft',saved.intro_draft); END $$;
CREATE FUNCTION public.sync_game_progress(p_intro jsonb,p_challenge jsonb,p_draft jsonb,p_path text,p_offset integer DEFAULT 0) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.sync_game_progress_safe(p_intro,p_challenge,p_draft,p_path,p_offset); END $$;
REVOKE ALL ON FUNCTION public.merge_game_json(jsonb,jsonb,jsonb),public.sync_game_progress_safe(jsonb,jsonb,jsonb,text,integer,jsonb),public.sync_game_progress(jsonb,jsonb,jsonb,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.sync_game_progress_safe(jsonb,jsonb,jsonb,text,integer,jsonb),public.sync_game_progress(jsonb,jsonb,jsonb,text,integer) TO authenticated;
CREATE TABLE public.day_notifications(user_id uuid NOT NULL,event_key text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,event_key));
GRANT SELECT ON public.day_notifications TO authenticated;
GRANT ALL ON public.day_notifications TO service_role;
ALTER TABLE public.day_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_day_notifications ON public.day_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());